head.script:
// 원본 : JLDFIL25900 배당기준일자 신고 (/ui/dis/account/JLDFIL25900.xml)

/*
 * 화면 동작
 * 1. 화면 로딩시 신고 목록을 조회
 * 2. 「작성하기」 클릭시 서버에 작성 가능 여부를 확인한 후 작성 화면으로 이동
 * 3. 목록의 신고명 클릭시 해당 건의 수정 화면으로 이동
 */


///////// 1. 변수 및 선언 영역 /////////

scwin.screenId = "JLDFIL25900";


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 08. 18
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        // 초기화 함수
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "JLDFIL25900.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 08. 18
 * @description 초기화. 안내문구의 연도를 채우고 목록을 조회한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    scwin.setNoticeYear();

    await scwin.searchList();
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_write_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 작성하기 버튼 클릭.
 *
 * 화면을 열기 전에 서버에 작성 가능한 상태인지 먼저 묻는다.
 * 화면을 연 뒤 저장할 때 막으면 사용자가 입력을 다 하고 나서 거절당한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_write_onclick = async function (e) {
    try {
        if (!await scwin.checkDeclarable()) return;

        $c.win.moveUrl("/ui/sample/template/JLDFIL25910.xml", {});
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "JLDFIL25900.btn_write_onclick" });
    }
};

/**
 * @event
 * @name scwin.grd_main_oncellclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 목록 행 클릭. 해당 건의 수정 화면으로 이동한다.
 *
 * 키만 넘기고 상세는 다음 화면이 다시 조회한다.
 * 행 전체를 넘기면 화면 간 결합이 생겨 컬럼이 바뀔 때 같이 깨진다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 넘길 키 이름
 * @param
 * @returns
 * @hidden N
*/
scwin.grd_main_oncellclick = function (rowIndex, columnIndex, columnId) {
    try {
        const bzProcsNo = dlt_main.getCellData(rowIndex, "bzProcsNo");

        $c.win.moveUrl("/ui/sample/template/JLDFIL25910.xml", { bzProcsNo: bzProcsNo });
    } catch (ex) {
        $c.exception.handleError(ex, { context : "JLDFIL25900.grd_main_oncellclick" });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.searchList
 * @author Inswave
 * @date 2026. 08. 18
 * @description 목록 조회. 신고 목록은 건수가 적어 페이징을 두지 않았다.
 *
 * 건수가 늘 수 있는 업무면 ULDFIL59400 의 페이징 부분을 가져다 쓴다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action, target
 * @param
 * @returns
 * @hidden N
*/
scwin.searchList = async function () {
    const sbmOptions = {
        id: "sbm_searchList",
        method: "get",
        action: "/api/discls/info/div-bas-dd/select-list",
        target: "dlt_main=body",
        gridview: "grd_main",
        isProcessMsg: false
    };

    // 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
    // 여기서 잡지 않으므로 오류가 나면 아래 코드는 실행되지 않는다.
    await $c.sbm.executeDynamic(sbmOptions);
};

/**
 * @method
 * @name scwin.checkDeclarable
 * @author Inswave
 * @date 2026. 08. 18
 * @description 지금 작성할 수 있는 상태인지 서버에 묻는다.
 *
 * 신고·접수처럼 기간이 정해진 업무는 화면을 열기 전과 저장 직전 두 번 확인한다.
 * 화면을 열어 둔 채로 마감이 지날 수 있기 때문이다.
 *
 * 사전 확인이 없는 업무면 이 함수와 호출부를 통째로 삭제한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action, 상태코드와 안내문구
 * @param
 * @returns
 * @hidden N
*/
scwin.checkDeclarable = async function () {
    const sbmOptions = {
        id: "sbm_checkDeclarable",
        method: "get",
        action: "/api/discls/info/div-bas-dd/decl-tp/select-one",
        isProcessMsg: false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);

    const declTpCd = result.responseJSON.body;

    if (declTpCd === "N") {
        await $c.win.alert("작성기간이 아닙니다.");
        return false;
    }

    if (declTpCd === "U") {
        await $c.win.alert("작성중인 건이 있습니다.");
        return false;
    }

    return true;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.setNoticeYear
 * @author Inswave
 * @date 2026. 08. 18
 * @description 안내문구의 연도를 채운다.
 *
 * 해가 바뀌면 저절로 따라가야 하는 값이라 마크업에 박아 두지 않는다.
 * 서버 일자를 쓴다. new Date() 는 사용자 PC 시각이라 기준이 흔들린다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 표시할 연도 기준
 * @param
 * @returns
 * @hidden N
*/
scwin.setNoticeYear = function () {
    const thisYear = $c.date.getServerDateTime("yyyy");

    txt_thisYear.setValue(thisYear);
    txt_lastYear.setValue(Number(thisYear) - 1);
};

/**
 * @method
 * @name scwin.dateFormatter
 * @author Inswave
 * @date 2026. 08. 18
 * @description 그리드 일자 컬럼 표시 형식. yyyyMMdd 를 yyyy-MM-dd 로 보여준다.
 *
 * 저장값은 그대로 두고 보이는 값만 바꾼다.
 * formatDate 의 두 번째 인자는 포맷 문자열이 아니라 구분자 한 글자다.
 * @param
 * @returns
 * @hidden N
*/
scwin.dateFormatter = function (data) {
    if ($c.util.isEmpty(data)) return "";

    return $c.date.formatDate(String(data).substring(0, 8), "-");
};
